/// <summary>
/// Data contract containing number of records pr status
/// </summary>
[DataContract]
public class OMGOutboundMessageStatusContract
{
    OMGProcessingStatus status;
    str     statusName;
    int64   records;

}

Method.Source:
/// <summary>
/// Read-only method returning status name
/// </summary>
/// <param name = "_statusName">Should not be populated</param>
/// <returns>the status name</returns>
[DataMember('Status')]
public str parmStatusName(str _statusName = statusName)
{
    DictEnum dictEnum = new DictEnum(enumNum(OMGProcessingStatus));
    statusName = dictEnum.value2Name(enum2int(status));

    return statusName;
}

public OMGProcessingStatus parmStatus(OMGProcessingStatus _status = status)
{
    status = _status;
    return status;
}

[DataMember('Records')]
public int64 parmRecords(int64 _records = records)
{
    records = _records;
    return records;
}
